const reduced=matchMedia('(prefers-reduced-motion: reduce)');
const menu=document.querySelector('.menu-toggle'),mobile=document.querySelector('#mobile-menu');
function closeMenu(){mobile.hidden=true;menu.setAttribute('aria-expanded','false');menu.querySelector('span').textContent='＋';document.body.classList.remove('menu-open');document.querySelector('main').inert=false}
menu.addEventListener('click',()=>{if(!mobile.hidden){closeMenu();return}mobile.hidden=false;menu.setAttribute('aria-expanded','true');menu.querySelector('span').textContent='−';document.body.classList.add('menu-open');document.querySelector('main').inert=true;mobile.querySelector('a').focus()});mobile.querySelectorAll('a').forEach(a=>a.addEventListener('click',closeMenu));document.querySelector('.header-contact').addEventListener('click',closeMenu);document.querySelector('header .brand').addEventListener('click',closeMenu);
addEventListener('keydown',e=>{if(e.key==='Escape'&&!mobile.hidden){closeMenu();menu.focus()}if(e.key==='Tab'&&!mobile.hidden){const focusables=[menu,...mobile.querySelectorAll('a')];const first=focusables[0],last=focusables[focusables.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
const reading=document.querySelector('.reading-progress'),hero=document.querySelector('.hero'),heroPhoto=document.querySelector('.hero-image');const clamp=(n,a=0,b=1)=>Math.min(b,Math.max(a,n));let scrollFrame=false;
function updatePage(){scrollFrame=false;const doc=document.documentElement;reading.style.width=`${clamp(scrollY/Math.max(1,doc.scrollHeight-innerHeight))*100}%`;if(reduced.matches||innerWidth<=600)return;const p=clamp(-hero.getBoundingClientRect().top/Math.max(1,hero.offsetHeight));heroPhoto.style.transform=`translateY(${p*28}px)`}
function schedulePage(){if(!scrollFrame){scrollFrame=true;requestAnimationFrame(updatePage)}}addEventListener('scroll',schedulePage,{passive:true});addEventListener('load',schedulePage);addEventListener('resize',()=>{heroPhoto.style.transform='';schedulePage()});reduced.addEventListener('change',()=>{heroPhoto.style.transform='';schedulePage()});schedulePage();
if('IntersectionObserver'in window&&!reduced.matches){const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');observer.unobserve(e.target)}}),{threshold:.08});document.querySelectorAll('.manifesto-line,.entrance-title,.entrance-side,.work-heading,.study,.material-heading,.site-intro,.site-note').forEach(el=>{el.classList.add('reveal');observer.observe(el)})}
