const imageSizes={2:[811,1062],3:[822,1068],4:[600,750],5:[960,640],6:[736,1104],8:[1600,900],10:[1600,1119],11:[960,960],12:[736,1312],13:[960,700]};
const viewer=document.querySelector('#viewer'),content=document.querySelector('#viewer-content');let lastFocus=null;
function openViewer(label){lastFocus=document.activeElement;viewer.setAttribute('aria-label',label);viewer.showModal();viewer.scrollTop=0;document.querySelector('.viewer-close').focus()}
function viewerHeading(titleText,description){const title=document.createElement('h2');title.className='viewer-title';title.textContent=titleText;const desc=document.createElement('p');desc.className='viewer-desc';desc.textContent=description;return [title,desc]}
document.querySelectorAll('[data-room]').forEach(b=>b.addEventListener('click',()=>{
 const room=rooms[Number(b.dataset.room)];content.replaceChildren();content.append(...viewerHeading(room.title,room.description));
 const observations=document.createElement('div');observations.className='viewer-observations';
 room.observations.forEach(([heading,text])=>{const item=document.createElement('section'),h=document.createElement('h3'),p=document.createElement('p');h.textContent=heading;p.textContent=text;item.append(h,p);observations.append(item)});
 content.append(observations);
 const gallery=document.createElement('div');gallery.className='viewer-gallery';
 room.images.forEach((n,i)=>{const figure=document.createElement('figure'),img=document.createElement('img'),caption=document.createElement('figcaption');img.src=`assets/photo-${String(n).padStart(2,'0')}.webp`;img.alt=room.captions[i];[img.width,img.height]=imageSizes[n];img.loading=i===0?'eager':'lazy';caption.textContent=room.captions[i]+' / Design visualisation';figure.append(img,caption);gallery.append(figure)});
 content.append(gallery);
 const note=document.createElement('p');note.className='viewer-source-note';note.textContent='Design visualisations from Pakeezah Atelier. Explore the finishes, proportions and light in each study.';content.append(note);
 const link=document.createElement('a');link.className='viewer-detail-link';link.href='#contact';link.textContent=room.study?'Have an entrance in mind? Begin a brief ↗':'Discuss your own space ↗';link.addEventListener('click',()=>viewer.close());content.append(link);
 openViewer(room.title);
}));
// Opening the complete image gives touch and keyboard users a useful inspection mode.
materialView.addEventListener('click',()=>{
 const data=materialData[activeMaterial];content.replaceChildren();
 content.append(...viewerHeading(data.title+' / up close.',data.note));
 const figure=document.createElement('figure');figure.className='material-detail-image';
 const img=document.createElement('img');img.src=data.source;img.alt=data.alt;
 const caption=document.createElement('figcaption');caption.textContent='Material detail / Design visualisation';
 figure.append(img,caption);content.append(figure);
 openViewer(data.title+' material detail');
});
