document.querySelectorAll('[data-film]').forEach(b=>b.addEventListener('click',()=>{
 const film=films[b.dataset.film];content.replaceChildren();
 const heading=document.createElement('div');heading.className='film-view-heading';const intro=document.createElement('div');intro.append(...viewerHeading(film.title,film.note));
 const meta=document.createElement('p');meta.className='film-view-meta';meta.textContent=film.topic+' / '+film.duration;const source=document.createElement('span');source.textContent='Original atelier footage / Silent film';meta.append(source);heading.append(intro,meta);
 const video=document.createElement('video');video.src=`assets/film-${b.dataset.film}.mp4`;video.poster=`assets/film-${b.dataset.film}.webp`;video.controls=true;video.playsInline=true;video.preload='metadata';video.className='viewer-film';video.setAttribute('aria-label',film.title+' — '+film.topic);
 const note=document.createElement('p');note.className='viewer-film-note';note.textContent='Original atelier footage. The films document spaces separately from the design visualisations.';
 content.append(heading,video,note);openViewer(film.title+' film');video.play().catch(()=>{});
}));
document.querySelector('.viewer-close').addEventListener('click',()=>viewer.close());viewer.addEventListener('close',()=>{content.querySelectorAll('video').forEach(v=>{v.pause();v.removeAttribute('src');v.load()});content.replaceChildren();lastFocus?.focus({preventScroll:true})});
let brief='';document.querySelector('#brief-form').addEventListener('submit',e=>{e.preventDefault();const data=new FormData(e.currentTarget);brief=`Hello Pakeezah Atelier, I'd like to discuss my space.\n\nName: ${data.get('name')}\nLocation: ${data.get('location')}\nSpace: ${data.get('type')}\nWhat I have in mind: ${data.get('vision')||'I would like to explore the possibilities.'}`;document.querySelector('#brief-text').textContent=brief;document.querySelector('#share-brief').href=`https://wa.me/917250071666?text=${encodeURIComponent(brief)}`;window.open(document.querySelector('#share-brief').href,'_blank','noopener,noreferrer');document.querySelector('#brief-result').hidden=false;document.querySelector('#brief-result').scrollIntoView({behavior:reduced.matches?'instant':'smooth',block:'center'})});
document.querySelector('#copy-brief').addEventListener('click',async()=>{try{await navigator.clipboard.writeText(brief);document.querySelector('#copy-status').textContent='Brief copied.'}catch{document.querySelector('#copy-status').textContent='Select the brief above and copy it manually.'}});
